'use strict';
let EVIDENCE, QA = null, ANALYSIS = null, PLAN = null, FRAME = null, QA_COVERAGE = null, ACQUISITION = null;
const state = {view:'overview', accountSearch:'', minVideos:1, sort:'videoCount', accountPage:1, qaSearch:'', qaTheme:'all', qaPage:1, planSearch:'',planPage:1};
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (v, digits=0) => v == null || !Number.isFinite(+v) ? 'Unavailable' : (+v).toLocaleString('en-US',{maximumFractionDigits:digits});
const pct = (n,d) => d ? fmt(100*n/d,1)+'%' : 'Unavailable';
const number = (v, fallback=0) => Number.isFinite(+v) ? +v : fallback;
const average = xs => xs.length ? xs.reduce((s,x)=>s+x,0)/xs.length : null;
function download(name, rows){
 const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];
 const quote=v=>{let text=String(v==null?'':typeof v==='object'?JSON.stringify(v):v);if(typeof v==='string'&&/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};
 const text='\ufeff'+[cols.map(quote).join(','),...rows.map(r=>cols.map(c=>quote(r[c])).join(','))].join('\r\n');
 const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function metric(n,label){return `<div class="metric"><strong>${fmt(n)}</strong><span>${label}</span></div>`;}
function bars(rows,{max, percent=false}={}){
 const scale=max??Math.max(1,...rows.map(r=>r.value));
 return rows.map(r=>`<div class="bar-row"><span class="bar-label">${esc(r.label)}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max(0,Math.min(100,100*r.value/scale))}%"></span></span><span class="bar-value">${fmt(r.value,percent?1:0)}${percent?'%':''}</span></div>`).join('');
}
function sourceDetails(title,body){return `<details><summary>${esc(title)}</summary>${body}</details>`;}
function overview(){
 const vs=EVIDENCE.videos, cs=EVIDENCE.channels, durations=vs.filter(v=>v.durationSeconds>0), active=cs.filter(c=>c.videoCount>0);
 const bins=[{label:'Under 5 minutes',value:0},{label:'5–15 minutes',value:0},{label:'15–30 minutes',value:0},{label:'30–60 minutes',value:0},{label:'60+ minutes',value:0}];
 durations.forEach(v=>{const m=v.durationSeconds/60;bins[m<5?0:m<15?1:m<30?2:m<60?3:4].value++;});
 const themes=EVIDENCE.topics.map(t=>({label:t.label,value:active.reduce((s,c)=>s+(c.topics.find(x=>x.id===t.id)?.count??0),0)}));
 const titleN=active.reduce((s,c)=>s+c.titleCount,0);
 const top=active.slice().sort((a,b)=>b.videoCount-a.videoCount).slice(0,8);
 const status=[{label:'Known duration',value:durations.length},{label:'Exact indexed date',value:vs.filter(v=>v.date).length},{label:'English-eligible title',value:vs.filter(v=>v.titleEligible).length},{label:'Downloaded captions (prior pilot)',value:EVIDENCE.transcripts.available??0}];
 return `<section aria-labelledby="collection-heading"><div class="section-heading"><h2 id="collection-heading">Collection &amp; material</h2><p>Frozen public metadata and numeric caption derivatives. New collection attempts are reported separately from retained records.</p></div>
 <div class="metrics">${metric(vs.length,'Indexed upload IDs')}${metric(durations.length,'Uploads with measured duration')}${metric(active.length,'Publishing accounts with uploads')}${metric(EVIDENCE.transcripts.englishPilotCount,'English caption pilot documents')}</div>
 <div class="two-columns"><section class="chart"><h3>Lengths of indexed uploads</h3><p>${fmt(durations.length)} uploads; whole-upload duration in minutes.</p>${bars(bins)}<p class="caption">Length includes introductions, promotion and other material. Unknown durations are excluded, not treated as zero. These are sample lengths, not channel-wide averages.</p></section>
 <section class="chart"><h3>Evidence available per upload</h3><p>Different evidence layers have different denominators.</p>${bars(status,{max:vs.length})}<p class="caption">Caption access was attempted on a purposive subset. This is not a caption-success rate for all ${fmt(vs.length)} uploads; language eligibility is a separate filter.</p></section></div>
 <div class="two-columns"><section class="chart"><h3>Keyword indicators in eligible titles</h3><p>Overlapping dictionary matches; ${fmt(titleN)} account-attributed eligible titles.</p>${bars(themes)}<p class="caption">An upload can match several categories. A title keyword measures publisher wording; it does not establish a spoken topic or answer agreement.</p></section>
 <section class="chart"><h3>Distribution across publishing accounts</h3><p>Eight largest indexed groups, by upload ID count.</p>${bars(top.map(c=>({label:c.name,value:c.videoCount})))}<p class="caption">Accounts can publish another practitioner’s recordings. Account concentration and missingness affect every comparison.</p></section></div>
 ${renderKeywordMatrix()}${renderAnalyticalFigures()}
 <div class="notice"><strong>Questions and answers are a separate evidence layer</strong>The retained source digests contain model-generated question and answer paraphrases associated with Darryl Anka recordings. They do not provide a multi-practitioner transcript dialogue corpus. <a href="#questions">Inspect candidate questions and their sources.</a></div>
 ${sourceDetails('Inspect source and denominator definitions',`<p>Source: <a href="../analysis/data.json">frozen analysis data.json</a>. Upload IDs are deduplicated; original recording/session reuse is unresolved. There are ${fmt(cs.length)} account records in the source, including zero-upload records; ${fmt(active.length)} have indexed uploads.</p><div class="source-block">SHA-256: ${esc(EVIDENCE.meta.baselineSha256)}</div><p>Duration bins use known positive seconds divided by 60. Topic counts sum per-account title indicator counts across attributed account groups; unattributed records do not enter these title sums. Caption pilot figures are retained evidence, not new inference.</p>`)}</section>`;
}
function renderAnalyticalFigures(){
 if(!ANALYSIS?.figures?.length)return '';
 return `<section><div class="section-heading"><h2>Expanded diagnostics</h2><p>Executed descriptive analyses of the retained evidence. Inspect the full methods beside the paper.</p></div><div class="figure-grid">${ANALYSIS.figures.map(f=>`<figure><a href="${esc(f.path)}"><img class="plot-image" src="${esc(f.path)}" alt="${esc(f.alt||f.title)}" loading="lazy"></a><figcaption><strong>${esc(f.title)}</strong> ${esc(f.caption||'')}</figcaption></figure>`).join('')}</div></section>`;
}
function renderKeywordMatrix(){
 if(!ANALYSIS?.keywordByDuration?.length)return '';
 const rows=ANALYSIS.keywordByDuration,bands=[...new Set(rows.map(r=>r.band))],topics=[...new Set(rows.map(r=>r.topic))];
 return `<section class="chart"><h3>Title keywords by upload length</h3><p>Share of eligible titles matching each overlapping dictionary category. Length bands are not speaker-verified formats.</p><div class="table-wrap matrix"><table><thead><tr><th scope="col">Title indicator</th>${bands.map(b=>`<th scope="col">${esc(b)}</th>`).join('')}</tr></thead><tbody>${topics.map(t=>`<tr><th scope="row">${esc(t)}</th>${bands.map(b=>{const r=rows.find(r=>r.topic===t&&r.band===b);return `<td><span class="heat-cell" style="background:rgba(64,92,73,${Math.max(.06,(r?.share??0)*.7)})" title="${r?`${r.matches} matches in ${r.eligibleTitles} eligible titles`:'No eligible titles'}">${r?.share!=null?fmt(r.share*100,1)+'%':'Unavailable'}</span><small>${r?`n = ${r.eligibleTitles}`:''}</small></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">Each cell uses its own eligible-title denominator. Dictionary categories overlap. Account mix can alter pooled direction; the research diagnostics compare pooled and within-account patterns.</p></section>`;
}
function collectionRows(){const s=state.planSearch.toLowerCase();return (PLAN?.searches||[]).filter(q=>!s||JSON.stringify(q).toLowerCase().includes(s));}
function collectionStatusText(){
 if(!ACQUISITION)return 'Acquisition summary is unavailable. Retained metadata is available; no live network status is inferred.';
 const when=ACQUISITION.checked_at?new Date(ACQUISITION.checked_at).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' New York time':'undated';
 const successful=ACQUISITION.new_successful_operations,blocked=ACQUISITION.recorded_blocks;
 return `Frozen acquisition ledger checked ${when}: ${fmt(successful)} new successful operations; ${fmt(blocked)} recorded ${blocked===1?'block':'blocks'}. ${blocked>0?'Access was blocked in the recorded probe. ':''}This is a snapshot, not a live network check.`;
}
function collectionNotice(){
 if(!ACQUISITION)return '<strong>Acquisition evidence unavailable</strong>The retained analytical snapshot remains inspectable. Collection status is unknown until a dated acquisition summary is available.';
 if(ACQUISITION.new_successful_operations>0)return `<strong>${fmt(ACQUISITION.new_successful_operations)} successful collection operations recorded</strong>The dated acquisition ledger is available separately. New results must be source-joined and reviewed before replacing the retained 925-upload analytical snapshot. ${fmt(ACQUISITION.recorded_blocks)} blocks are also recorded.`;
 return `<strong>No successful new YouTube operations in this frozen release</strong>The dated ledger records ${fmt(ACQUISITION.recorded_preflight_attempts)} ordinary public-watch preflight attempt and ${fmt(ACQUISITION.recorded_blocks)} block. The recorded probe returned a proxy 403; it does not establish current live access. The collection plan remains unexecuted. The retained 925-upload snapshot remains available.`;
}
function collection(){
 const units=PLAN?.units||{};
 return `<section><div class="section-heading"><h2>Channel and keyword collection plan</h2><p>Review inherited candidate identities and the queries prepared for each. These rows are planned operations, not new search results.</p></div><div class="metrics">${metric(units.practitioner_candidates,'Inherited practitioner / lineage candidates')}${metric(units.keyword_queries,'Planned keyword queries')}${metric(units.account_routes,'Inherited account routes')}${metric(units.caption_candidates,'Selected caption candidates')}</div><div class="notice">${collectionNotice()}</div><form id="plan-filters" class="controls"><label>Practitioner, entity or query keyword<input name="planSearch" type="search" placeholder="Try Bashar, Ashtar, Pleiadian…" value="${esc(state.planSearch)}"></label><button class="button" type="submit">Filter candidate roster &amp; queries</button><a href="collection-plan.json" class="button secondary" download>Download complete plan</a></form><div id="coverage-results">${coverageResults()}</div><div id="plan-results">${collectionResults()}</div>${sourceDetails('Identity and sampling notes',`<p>${esc(PLAN?.scope||'Inherited candidate records are not a deduplicated census of human mediums.')}</p><p>${esc(PLAN?.selection_policy||'Collection uses fixed query templates, per-account limits, source records and explicit access status.')}</p><p>Candidate aliases and entity names are inherited leads, not revalidated identity joins. The identity map retains original source record IDs and unresolved attribution.</p><div class="download-links"><a href="identity-map.json" download>Identity map</a><a href="practitioner-frame.json" download>Practitioner frame</a><a href="qa-practitioner-coverage.json" download>Q&A evidence coverage</a><a href="acquisition-status.json" download>Dated acquisition summary</a><a href="acquisition-preflight.json" download>Original preflight receipt</a></div>`)}</section>`;
}
function coverageResults(){
 const s=state.planSearch.toLowerCase(),rows=(QA_COVERAGE?.records||[]).filter(r=>!s||[r.name,...(r.contextEntityLabels||[])].join(' ').toLowerCase().includes(s));
 return `<section><div class="section-heading"><h3>Candidate identity and Q&A coverage</h3><p>${fmt(rows.length)} matching inherited records. Zero means no usable Q&A text in this release, not that the practitioner has never answered questions.</p></div><div class="table-wrap roster"><table><thead><tr><th scope="col">Inherited candidate</th><th scope="col">Contextual entity labels</th><th scope="col">Q&A candidates</th><th scope="col">Source / identity status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc((r.contextEntityLabels||[]).join(', ')||'Unresolved')}</td><td class="numeric">${fmt(r.qaCandidateCount)}<small>${r.qaCandidateCount?'Digest paraphrases':'No usable text in this release'}</small></td><td>${r.sourceUrls?.[0]?`<a href="${esc(r.sourceUrls[0])}" target="_blank" rel="noopener">Inherited source lead ↗</a>`:'No source lead'}<small>Candidate; not revalidated</small></td></tr>`).join('')||'<tr><td colspan="4">No inherited candidate matches this filter.</td></tr>'}</tbody></table></div></section>`;
}
function collectionResults(){
 const rows=collectionRows(),pages=Math.max(1,Math.ceil(rows.length/20));state.planPage=Math.min(state.planPage,pages);const page=rows.slice((state.planPage-1)*20,state.planPage*20);
 return `<p class="result-count">${fmt(rows.length)} matching planned queries</p><div class="table-wrap"><table><thead><tr><th>Candidate practitioner / lineage</th><th>Planned query</th><th>Execution status</th></tr></thead><tbody>${page.map(q=>`<tr><td>${esc(q.practitioner_name||q.person_name||q.practitioner||q.name||q.person_id||q.practitioner_id||'Inherited candidate')}</td><td>${esc(q.query||q.search_query||q.keyword||'')}</td><td>Planned; not executed<small>Access prerequisite unresolved</small></td></tr>`).join('')}</tbody></table></div>${pager('plan',state.planPage,pages,rows.length)}`;
}
function accountRows(){
 const s=state.accountSearch.toLowerCase();return EVIDENCE.channels.filter(c=>c.videoCount>=state.minVideos&&(!s||[c.name,c.url,...(c.nameAliases||[])].join(' ').toLowerCase().includes(s))).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):number(b[state.sort],-1)-number(a[state.sort],-1));
}
function accounts(){return `<section><div class="section-heading"><h2>Publishing accounts</h2><p>Compare whole-upload lengths and evidence coverage. Names identify publishing groups; they do not establish the on-screen speaker.</p></div><form class="controls" id="account-filters"><label>Account name or alias<input name="accountSearch" type="search" value="${esc(state.accountSearch)}" placeholder="Search publishing accounts"></label><label>Minimum indexed uploads<select name="minVideos">${[0,1,5,10,25].map(n=>`<option value="${n}"${state.minVideos===n?' selected':''}>${n===0?'Include zero-upload records':n+'+'}</option>`).join('')}</select></label><label>Order<select name="sort">${[['videoCount','Indexed uploads'],['meanMinutes','Mean length'],['transcriptCount','Caption pilot documents'],['name','Account name']].map(([v,l])=>`<option value="${v}"${state.sort===v?' selected':''}>${l}</option>`).join('')}</select></label><button class="button" type="submit">Apply filters</button></form><div id="account-results">${accountResults()}</div><p class="caption">Missing values stay unavailable. Mean, median and quartiles use measured uploads within each account. Caption pilot zero means no contributing pilot document, not that the account has no captions.</p>${sourceDetails('How to interpret account comparisons','<p>Account routes were merged only using explicit aliases. Unknown publisher attribution remains unresolved. Differences in formats, language, selection and reposts can explain differences in duration and title vocabulary; these comparisons do not identify an entity effect.</p>')}</section>`;}
function accountResults(){
 const rows=accountRows(),pages=Math.max(1,Math.ceil(rows.length/15));state.accountPage=Math.min(state.accountPage,pages);const page=rows.slice((state.accountPage-1)*15,state.accountPage*15);
 return `<div class="section-heading"><p class="result-count">${fmt(rows.length)} matching account groups</p><button class="button secondary" data-action="export-accounts">Export filtered accounts CSV</button></div>${page.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Publishing account</th><th scope="col">Indexed uploads</th><th scope="col">Measured lengths</th><th scope="col">Mean / median (min)</th><th scope="col">Middle 50% (min)</th><th scope="col">English titles</th><th scope="col">Caption pilot</th></tr></thead><tbody>${page.map(c=>`<tr><td><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)}</a><small>${esc(c.relationship||'Attribution unresolved')} · <a href="../#/analysis">Retained source analysis</a></small></td><td class="numeric">${fmt(c.videoCount)}</td><td class="numeric">${fmt(c.durationCount)}<small>${pct(c.durationCount,c.videoCount)} coverage</small></td><td class="numeric">${fmt(c.meanMinutes,1)} / ${fmt(c.medianMinutes,1)}</td><td class="numeric">${fmt(c.q1Minutes,1)}–${fmt(c.q3Minutes,1)}</td><td class="numeric">${fmt(c.titleCount)}</td><td class="numeric">${fmt(c.transcriptCount)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No account matches these filters. Try another name or lower the upload threshold.</p>'}${pager('accounts',state.accountPage,pages,rows.length)}`;
}
function pager(kind,page,pages,total){return `<div class="pager"><span>Page ${page} of ${pages} · ${fmt(total)} records</span><div><button class="button secondary" data-action="prev-${kind}"${page===1?' disabled':''}>Previous</button><button class="button secondary" data-action="next-${kind}"${page===pages?' disabled':''}>Next</button></div></div>`;}
function qaRows(){
 const rows=QA?.records||[],s=state.qaSearch.toLowerCase();return rows.filter(q=>(!s||[q.question,q.answer,...(q.themes||[]),q.publisher,q.practitioner].join(' ').toLowerCase().includes(s))&&(state.qaTheme==='all'||q.themes?.includes(state.qaTheme)));
}
function questions(){
 if(!QA)return `<section><h2>Question &amp; answer candidates</h2><div class="notice"><strong>Extraction is being prepared</strong>The database is being generated from retained source digests. No newly retrieved transcript dialogue is available in this environment. Existing title and embedding similarity is not answer agreement.</div></section>`;
 const themes=[...new Set(QA.records.flatMap(q=>q.themes||[]))].sort();
 return `<section><div class="section-heading"><h2>Question &amp; answer candidates</h2><p>Search derived paraphrases, inspect their upload source, and keep speaker attribution uncertainty visible.</p></div><div class="metrics">${metric(QA.records.length,'Digest-paraphrase Q&A candidates')}${metric(new Set(QA.records.map(q=>q.videoId)).size,'Source uploads with Q&A candidates')}${metric(new Set(QA.records.map(q=>q.practitioner).filter(Boolean)).size,'Source-attributed practitioners')}${metric(0,'Human-validated transcript Q&A turns')}</div><div class="notice"><strong>Cross-practitioner answer comparison is unavailable</strong>All retained digest Q&A candidates are associated with Darryl Anka recordings. Publisher groups are not distinct practitioners. These summaries are model-generated paraphrases, not verbatim questions, speaker-verified dialogue or a measure of answer agreement.</div><p class="caption">Publisher attribution: ${fmt(QA.coverage.publishingAccountsWithQA)} resolved account IDs and ${fmt(QA.coverage.unresolvedPublisherNameGroups)} unresolved name groups (${fmt(QA.coverage.candidatesWithoutResolvedPublisherId)} candidates). The full source archive has 75 digests; 67 contain these Q&A candidates. <a href="#collection">Inspect the 106-candidate coverage roster.</a></p><form class="controls" id="qa-filters"><label>Question, answer or keyword<input name="qaSearch" type="search" value="${esc(state.qaSearch)}" placeholder="Try contact, beliefs, relationships…"></label><label>Keyword theme<select name="qaTheme"><option value="all">All themes</option>${themes.map(t=>`<option${state.qaTheme===t?' selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label><button class="button" type="submit">Apply filters</button></form><div id="qa-results">${questionResults()}</div>${commonQuestions()}<div class="download-links"><a href="qa-candidates.sqlite" download>Q&A SQLite database</a><a href="qa-summary.json" download>Q&A methods and coverage JSON</a><a href="qa-close-reading.json" download>20-candidate model close-reading record</a></div>${sourceDetails('Extraction status and source interpretation','<p>Questions and answer gists are existing model-generated digest fields. Keyword themes are deterministic dictionary matches and may overlap. Practitioner association is inherited from the source archive. Interview hosts, quoted speech, promotions and claimed entity speech have not been separated by listening or diarization.</p><p>A source link permits inspection of the recording, not a guarantee of playback, caption availability or the accuracy of its digest. No raw caption text is redistributed here. The 20-candidate close-reading pass inspected digest paraphrases only; it is not human validation or direct audiovisual understanding.</p>')}</section>`;
}
function questionResults(){
 const rows=qaRows(),pages=Math.max(1,Math.ceil(rows.length/12));state.qaPage=Math.min(state.qaPage,pages);const page=rows.slice((state.qaPage-1)*12,state.qaPage*12);
 return `<div class="section-heading"><p class="result-count">${fmt(rows.length)} matching Q&A candidates · model-generated digest paraphrases</p><button class="button secondary" data-action="export-qa">Export filtered candidates CSV</button></div><div class="question-list">${page.map(q=>`<article class="question"><div class="question-meta">${esc(q.practitioner||'Practitioner unresolved')} · ${esc(q.publisher||'Publisher unresolved')}</div><h3>${esc(q.question)}</h3><p class="answer">${esc(q.answer)}</p><div>${(q.themes||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="evidence-depth">Digest paraphrase · ${esc(q.entityStatus||'Claimed entity / actual speaker unresolved')} · ${esc(q.timestamp==null?'No verified timestamp':q.timestamp)}</p><div class="question-source"><a href="${esc(q.url)}" target="_blank" rel="noopener">Inspect source recording ↗</a><span>Candidate ${esc(q.id)}</span></div></article>`).join('')||'<p class="empty">No candidate matches these filters. Try a broader term or choose all themes.</p>'}</div>${pager('qa',state.qaPage,pages,rows.length)}`;
}
function commonQuestions(){
 const pairs=QA?.pairs||[];if(!pairs.length)return '';
 return `<section><div class="section-heading"><h2>Related question candidates</h2><p>Lexical neighbors within the Darryl Anka digest corpus. Similar wording does not establish equivalent answers.</p></div><p class="caption">10 highest-scoring pairs displayed; <a href="qa-question-pairs.json" download>download all ${fmt(QA.coverage.questionSimilarityPairsAt040)} qualifying candidate pairs</a>. Cross-upload question cosine cutoff ≥ 0.40. The compact data snapshot retains the first ${fmt(QA.pairPreview.sourcePreviewCount)}; the linked full artifact contains all ${fmt(QA.pairPreview.fullPairCount)}.</p><div class="table-wrap"><table><thead><tr><th>Question A</th><th>Question B</th><th>Lexical similarity</th><th>Inspect paired sources</th></tr></thead><tbody>${pairs.slice(0,10).map(p=>`<tr><td>${esc(p.questionA)}</td><td>${esc(p.questionB)}</td><td>${fmt(p.similarity,3)}</td><td><details><summary>Sources &amp; comparison limits</summary><p><a href="https://www.youtube.com/watch?v=${esc(p.leftVideoId)}" target="_blank" rel="noopener">Recording A ↗</a><br><a href="https://www.youtube.com/watch?v=${esc(p.rightVideoId)}" target="_blank" rel="noopener">Recording B ↗</a></p><p>Original-session independence: ${esc(p.originalSessionIndependence)}. Answer agreement: ${esc(p.answerAgreement).replaceAll('_',' ')}. Answer-gist lexical cosine: ${fmt(p.answerCosine,3)}.</p><small>Candidate IDs: ${esc(p.leftId)} / ${esc(p.rightId)}</small></details></td></tr>`).join('')}</tbody></table></div><p class="caption">TF-IDF cosine similarity is a retrieval aid. These pairs are candidates for close reading, not validated question equivalence, independent corroboration, or shared extraterrestrial origin. Two upload IDs can contain the same original session.</p><p class="caption"><a href="qa-pair-close-reading.json" download>12-pair model-assisted close-reading record</a> · Digest paraphrases only; answer agreement remains undetermined; no human or audiovisual validation.</p>${questionSensitivity()}</section>`;
}
function questionSensitivity(){
 const rows=QA.sensitivity?.retrievalThresholds||[],concentration=QA.sensitivity?.uploadPairConcentration;
 if(!rows.length)return '';
 return `<section class="chart" id="qa-sensitivity"><h3>Question retrieval sensitivity</h3><p>Cross-upload candidate pairs retained at each question-cosine cutoff.</p>${bars(rows.map(r=>({label:'Cosine ≥ '+r.minimumQuestionCosine.toFixed(2),value:r.candidatePairs})))}<div class="table-wrap"><table><thead><tr><th scope="col">Question cosine cutoff</th><th scope="col">Candidate Q&A pairs</th><th scope="col">Distinct upload pairs</th></tr></thead><tbody>${rows.map(r=>`<tr><td>≥ ${r.minimumQuestionCosine.toFixed(2)}</td><td>${fmt(r.candidatePairs)}</td><td>${fmt(r.distinctUploadPairs)}</td></tr>`).join('')}</tbody></table></div><p class="caption">These are retrieval thresholds, not validated agreement levels. Raising the cutoff changes the candidate set. ${concentration?`${fmt(concentration.totalQuestionPairs)} candidate pairs at 0.40 span ${fmt(concentration.distinctUploadPairs)} upload pairs; the three largest upload-pair groups contribute ${fmt(concentration.topThreeUploadPairCandidateMatches)} matches. This is lexical-match concentration, not a measured repost rate.`:''}</p></section>`;
}
function methods(){
 const plans=PLAN?.queries||PLAN?.records||[];
 return `<section><div class="section-heading"><h2>Methods &amp; limits</h2><p>What was executed, what the evidence can support, and what still requires access or validation.</p></div><div class="two-columns"><section class="chart"><h3>Executed evidence layers</h3><ul><li>Retained metadata for ${fmt(EVIDENCE.videos.length)} unique upload IDs.</li><li>Per-account whole-upload duration and title keyword indicators.</li><li>Previously computed lexical and pinned neural title/caption derivatives.</li><li>Source-linked model-generated digest Q&A candidates, when available.</li><li>New analytical diagnostics with fixed inputs and explicit denominator checks.</li></ul></section><section class="chart"><h3>Outstanding evidence</h3><ul><li>New channel crawls and keyword-search results require permitted YouTube access.</li><li>Multi-practitioner transcript Q&A and speaker/host segmentation.</li><li>Human review of caption accuracy, question equivalence and answer agreement.</li><li>Original-session family resolution and domain encoder validation.</li><li>Physical-origin claims require a separate evidentiary design.</li></ul></section></div>
 <div class="notice"><strong>Third-party tools do not remove access limits</strong>The acquisition workflow uses public metadata and offered captions through documented open-source software. It does not use residential-proxy rotation, private cookies, CAPTCHA bypass, paid recordings or inaccessible transcripts as a workaround.</div>
 ${sourceDetails('Channel crawling, search and sampling',`<p>A practitioner/entity alias frame produces a versioned keyword query plan. A planned query is not an executed search result. The executed selection rule preserves the historical pilot, then chooses one nonpilot upload per publisher in deterministic order. The query plan uses fixed name/entity templates and all inherited account routes. Deduplication by video ID, retrieval failures and stop-on-block behavior are recorded; language/format stratification is a proposed extension, not a completed collection.</p><p>Public watch metadata can be present even when playback or captions are unavailable. Upload dates can differ from original session dates. Exact dates are kept separate from approximate title-derived dates.</p><div class="download-links"><a href="collection-plan.json" download>Query plan JSON</a><a href="identity-map.json" download>Identity mapping JSON</a><a href="acquisition-status.json" download>Acquisition status JSON</a></div>`) }
 ${sourceDetails('Keyword-based extraction',`<p>Title indicators and Q&A themes use transparent dictionary matching with recorded term patterns. Categories overlap. Counts describe sampled text artifacts and are not validated measures of belief, clinical state, topic intensity or answer agreement. Digest question retrieval uses separate question and answer TF-IDF fits: word unigrams/bigrams, English stop words, sublinear term frequency, smooth inverse document frequency and L2 normalization. Cross-upload question pairs enter the retrieval table at cosine ≥ 0.40. This is a candidate retrieval threshold, not a validated equivalence threshold; it does not infer speaker turns.</p><p>The methodology distinguishes metadata, existing numeric derivatives, model-generated paraphrase annotations and raw transcript evidence. Only collected evidence contributes empirical counts.</p>`) }
 ${sourceDetails('Attribution and unit of analysis',`<p>Practitioner, publishing account, claimed entity, upload and original session are different units. Aliases merge only with supporting source evidence. Unknown attribution remains unknown. Re-uploaded recordings can make upload-level observations dependent, even after video-ID deduplication.</p>`) }
 ${sourceDetails('Sampling, uncertainty and novelty',`<p>The source frame is a curated convenience sample. Caption access and English-language eligibility induce selection. Descriptive resampling or leave-account-out ranges are sensitivity diagnostics; they do not make this a representative census. Hypotheses about format, segmentation and shared questions remain hypotheses unless executed checks support a bounded observation.</p><p>Model-agent panels provide independent implementation checks, not human peer review. The scholarly comparison documents what prior YouTube research actually did and separates full-text reading from abstract-only or unavailable access.</p>`) }
 <div class="download-links"><a href="paper.pdf">Current expansion paper PDF</a><a href="source.zip" download>Current paper source ZIP</a><a href="../analysis/channeling-atlas-paper.pdf">Earlier rounds 1–6 paper</a></div><div class="source-block"><strong>Frozen analytical source</strong><br><a href="../analysis/data.json">analysis/data.json</a><br>SHA-256 ${esc(EVIDENCE.meta.baselineSha256)}<br>Evidence cutoff: ${esc(EVIDENCE.meta.evidenceCutoff)}<br>Downloads preserve the filtered rows and their source classifications.</div></section>`;
}
function render(){
 state.view=['overview','accounts','collection','questions','methods'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
 document.body.dataset.view=state.view;
 document.querySelectorAll('.view-nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+state.view?'page':'false'));
 const nav=$('.view-nav'),selected=nav.querySelector('[aria-current=page]');
 if(selected)nav.scrollLeft=Math.max(0,selected.offsetLeft-nav.offsetLeft+selected.offsetWidth-nav.clientWidth+12);
 $('#app').innerHTML=({overview,accounts,collection,questions,methods})[state.view]();
 document.title=({overview:'Collection & material',accounts:'Publishing accounts',collection:'Collection plan',questions:'Q&A candidates',methods:'Methods & limits'})[state.view]+' — Channeling Atlas';
}
document.addEventListener('submit',e=>{
 if(e.target.id==='account-filters'){e.preventDefault();const f=new FormData(e.target);state.accountSearch=f.get('accountSearch').trim();state.minVideos=+f.get('minVideos');state.sort=f.get('sort');state.accountPage=1;$('#account-results').innerHTML=accountResults();}
 if(e.target.id==='qa-filters'){e.preventDefault();const f=new FormData(e.target);state.qaSearch=f.get('qaSearch').trim();state.qaTheme=f.get('qaTheme');state.qaPage=1;$('#qa-results').innerHTML=questionResults();}
 if(e.target.id==='plan-filters'){e.preventDefault();const f=new FormData(e.target);state.planSearch=f.get('planSearch').trim();state.planPage=1;$('#plan-results').innerHTML=collectionResults();$('#coverage-results').innerHTML=coverageResults();}
});
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='export-accounts')download('channeling-atlas-filtered-accounts.csv',accountRows().map(c=>({account_id:c.id,publisher:c.name,url:c.url,indexed_uploads:c.videoCount,measured_duration_count:c.durationCount,mean_minutes:c.meanMinutes,median_minutes:c.medianMinutes,q1_minutes:c.q1Minutes,q3_minutes:c.q3Minutes,eligible_title_count:c.titleCount,caption_pilot_count:c.transcriptCount,unit:'Publishing account, not speaker'})));
 if(action==='export-qa')download('channeling-atlas-filtered-qa-candidates.csv',qaRows());
 if(action==='prev-accounts'||action==='next-accounts'){state.accountPage+=action.startsWith('next')?1:-1;$('#account-results').innerHTML=accountResults();$('#account-results').scrollIntoView({block:'start'});}
 if(action==='prev-qa'||action==='next-qa'){state.qaPage+=action.startsWith('next')?1:-1;$('#qa-results').innerHTML=questionResults();$('#qa-results').scrollIntoView({block:'start'});}
 if(action==='prev-plan'||action==='next-plan'){state.planPage+=action.startsWith('next')?1:-1;$('#plan-results').innerHTML=collectionResults();$('#plan-results').scrollIntoView({block:'start'});}
});
addEventListener('hashchange',()=>{render();$('#main').scrollIntoView({block:'start'});});
async function readOptional(path){try{const r=await fetch(path);return r.ok?await r.json():null;}catch{return null;}}
(async()=>{
 try{const r=await fetch('evidence.json');if(!r.ok)throw new Error('Metadata snapshot unavailable');EVIDENCE=await r.json();
 [QA,ANALYSIS,PLAN,FRAME,QA_COVERAGE]=await Promise.all(['qa.json','diagnostics.json','collection-plan.json','identity-map.json','qa-practitioner-coverage.json'].map(readOptional));
 ACQUISITION=await readOptional('acquisition-status.json');
 $('#collection-status').textContent=collectionStatusText();
 render();
 }catch(error){$('#app').innerHTML=`<div class="error"><h2>Evidence could not be loaded</h2><p>${esc(error.message)}</p><p>Use the <a href="../analysis/report.html">static report</a> or <a href="evidence.json">download the metadata snapshot</a>.</p><button class="button" onclick="location.reload()">Retry</button></div>`;}
})();
